// Fail closed on damaged browser state, preserving the original text for recovery.
export function parseSavedState(text){
 const state=JSON.parse(text||'{}'),object=v=>v!==null&&typeof v==='object'&&!Array.isArray(v),strings=v=>Array.isArray(v)&&v.every(x=>typeof x==='string');
 const draft=v=>object(v)&&(!v.stableEmployees||strings(v.stableEmployees))&&(!v.stableShrink||strings(v.stableShrink))&&(!v.stableNotes||object(v.stableNotes))&&(!v.stableRoles||object(v.stableRoles)&&['rx','training','earlyLate'].every(k=>!v.stableRoles[k]||strings(v.stableRoles[k])));
 const forecast=f=>object(f)&&object(f.plan)&&typeof f.plan.date==='string'&&object(f.prediction)&&Number.isFinite(f.prediction.displayHours)&&Number.isFinite(f.prediction.laborHours)&&strings(f.crewNames)&&typeof f.releaseVersion==='string';
 if(!object(state)||state.draft&&!draft(state.draft)||state.forecasts&&(!Array.isArray(state.forecasts)||!state.forecasts.every(forecast))||state.storePlans&&(!object(state.storePlans)||!Object.values(state.storePlans).every(draft)))throw Error('Invalid saved planner state');
 for(const key of ['filters','compareNotes','pasteFeedback'])if(state[key]&&!object(state[key]))throw Error('Invalid saved planner state');
 if(state.pasteFeedback&&['setup','compare'].some(k=>state.pasteFeedback[k]&&!strings(state.pasteFeedback[k])))throw Error('Invalid saved paste feedback');
 if(state.compare){const c=state.compare;if(!object(c)||c.values&&!object(c.values)||['stableAvailable','stableStores','stableSupervisors'].some(k=>c[k]&&!strings(c[k]))||c.stableRoles&&(!object(c.stableRoles)||['rx','training','earlyLate'].some(k=>c.stableRoles[k]&&!strings(c.stableRoles[k]))))throw Error('Invalid saved comparison');}
 return state;
}

export function lastCrewSelection(snapshot,last){
 const ids=new Set(snapshot.persons.map(p=>p.key)),supervisor=ids.has(last.supervisor)?last.supervisor:'';
 const employees=[...new Set([...(last.employees||[]),...(supervisor?[supervisor]:[])])].filter(id=>ids.has(id));
 return {employees,supervisor,rx:(last.rx||[]).filter(id=>employees.includes(id))};
}

export function forecastSignature(plan,snapshot,release){
 return JSON.stringify([persistentDraft(plan,snapshot),snapshot.dataFingerprint,snapshot.modelSha256,release.files.planning.sha256,release.version]);
}



export function rankedSearch(items,query){

 const clean=s=>String(s).normalize('NFKD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]+/g,' ').trim();

 const q=clean(query),tokens=q.split(/\s+/).filter(Boolean);

 return items.map(item=>{const name=clean(item.name),words=name.split(' '),tail=clean(item.name.split(' / ').slice(1).join(' ')),initials=words.map(w=>w[0]).join('');

 let score=!q?5:name===q?0:tail===q?1:name.startsWith(q)||tail.startsWith(q)?2:tokens.every(t=>words.some(w=>w.startsWith(t)))?3:name.includes(q)?4:tokens.every(t=>name.includes(t))?5:initials.startsWith(q.replaceAll(' ',''))?6:Infinity;

 return {item,score};}).filter(r=>Number.isFinite(r.score)).sort((a,b)=>a.score-b.score||a.item.name.localeCompare(b.item.name)).map(r=>r.item);

}



export function weeklyDataStatus(snapshot,now=new Date()){

 const date=[now.getFullYear(),String(now.getMonth()+1).padStart(2,'0'),String(now.getDate()).padStart(2,'0')].join('-');

 return {date,valid:date>=snapshot.cutoff&&date<=snapshot.validThrough,message:'This planning week has expired or is not current. Ask the owner to build the current week.'};

}

export function selectionProduction(snapshot,id,storeKey,variant='default',recent=false){

 const store=snapshot.stores.find(s=>s.key===storeKey),pack=store?.scenario?.variants[variant],rate=snapshot.scenarioRates?.[pack?.[recent?'recentRates':'rates']]?.[id];

 if(!store)return {speed:null,basis:'Choose a store',context:''};if(!pack)return {speed:null,basis:'No supported '+variant+' rate',context:store.name.split(' / ')[0]+' · '+variant};

 const context=store.name.split(' / ')[0]+' · '+(pack.inventoryMode===true?'Modas':pack.inventoryMode===false?'regular':'mixed mode');

 if(!rate||!Number.isFinite(rate[0])||rate[0]<0||rate[0]===0&&!rate[1])return {speed:null,basis:'No production estimate',context};

 return {speed:rate[0],basis:rate[2]>0?'account-history estimate':rate[1]?'broader-history estimate':'prior estimate',context};

}



